class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # count how many k‑windows contain each value
        cnt = defaultdict(int)

        # enumerate all windows of length k
        for start in range(n - k + 1):
            window = nums[start:start + k]
            for v in window:
                cnt[v] += 1

        # find the largest value that appears exactly once
        answer = -1
        for v, c in cnt.items():
            if c == 1 and v > answer:
                answer = v
        return answer

