        rev_adj = [[] for _ in range(n)]
        for a, b, w in edges:
            rev_adj[b].append((a, w))

        dist = [INF] * n
        dist[0] = 0
        heap = [(0, 0)]                     # (current max edge weight, vertex)

        while heap:
            d, v = heapq.heappop(heap)
            if d != dist[v]:
                continue
            for to, w in rev_adj[v]:
                nd = d if d >= w else w   # max(d, w) without function call
                if nd < dist[to]:
                    dist[to] = nd
                    heapq.heappush(heap, (nd, to))

        # if some vertex was never reached, impossible
        if any(d == INF for d in dist):
            return -1

        # answer = maximal minimal bottleneck over all vertices
        return max(dist)

