    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp maps (next_parity, alternating_sum) -> maximal product (≤ limit)
        dp: Dict[Tuple[int, int], int] = {}

        for num in nums:
            ndp = dp.copy()                     # case: skip current number

            # start a new subsequence with the current number
            if num <= limit:                     # product must respect limit
                key = (1, num)                    # after first element, next pos is odd
                ndp[key] = max(ndp.get(key, -1), num)

            # extend all already existing subsequences
            for (par, s), prod in dp.items():
                new_par = 1 - par
                new_sum = s + num if par == 0 else s - num
                new_prod = prod * num
                if new_prod <= limit:
                    key = (new_par, new_sum)
                    if new_prod > ndp.get(key, -1):
                        ndp[key] = new_prod

            dp = ndp

        # find the best product among states whose sum equals k
        best = -1
        for (par, s), prod in dp.items():
            if s == k and prod > best:
                best = prod
        return best

