class SegmentTree:
    """Segment tree that stores the maximum value in a range."""
    def __init__(self, data: List[int]):
        n = len(data)
        self.n = n
        self.size = 1
        while self.size < n:
            self.size <<= 1
        # tree of size 2*size, initialise with very small numbers
        self.tree = [-10**18] * (2 * self.size)
        # fill leaves
        for i, v in enumerate(data):
            self.tree[self.size + i] = v
        # build internal nodes
        for i in range(self.size - 1, 0, -1):
            self.tree[i] = max(self.tree[i << 1], self.tree[(i << 1) | 1])

    def _update(self, pos: int, value: int):
        """set leaf at position `pos` to `value`."""
        i = self.size + pos
        self.tree[i] = value
        i >>= 1
        while i:
            self.tree[i] = max(self.tree[i << 1], self.tree[(i << 1) | 1])
            i >>= 1

    def update_to_negative_inf(self, pos: int):
        """mark position `pos` as occupied (value smaller than any possible fruit)."""
        self._update(pos, -10**18)

    def _find_first(self, node: int, l: int, r: int, value: int) -> int:
        """return smallest index in [l, r] with tree[node] >= value, or -1."""
        if self.tree[node] < value:
            return -1
        if l == r:
            return l
        mid = (l + r) // 2
        left_res = self._find_first(node << 1, l, mid, value)
        if left_res != -1:
            return left_res
        return self._find_first((node << 1) | 1, mid + 1, r, value)

    def find_leftmost_ge(self, value: int) -> int:
        """public wrapper for the search over the whole array."""
        return self._find_first(1, 0, self.size - 1, value)


