class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)

        # 1. store distinct values of each row as a set
        sets = [set(row) for row in properties]

        # 2. build adjacency list
        graph = [[] for _ in range(n)]
        for i in range(n):
            si = sets[i]
            for j in range(i + 1, n):
                # size of intersection
                if len(si & sets[j]) >= k:
                    graph[i].append(j)
                    graph[j].append(i)

        # 3. DFS to count components
        visited = [False] * n
        def dfs(v: int) -> None:
            stack = [v]
            visited[v] = True
            while stack:
                cur = stack.pop()
                for nb in graph[cur]:
                    if not visited[nb]:
                        visited[nb] = True
                        stack.append(nb)

        components = 0
        for i in range(n):
            if not visited[i]:
                components += 1
                dfs(i)

        return components

