    def __init__(self, val):
        self.val = val
        self.prio = random.randint(1, 1 << 30)
        self.size = 1
        self.left = None
        self.right = None


def get_size(node):
    return node.size if node else 0


def update(node):
    if node:
        node.size = 1 + get_size(node.left) + get_size(node.right)


def split(root, k):
    """
    Split treap into (left, right) where left contains first k elements.
    """
    if not root:
        return (None, None)
    if get_size(root.left) >= k:
        # desired split is entirely in left subtree
        left, right = split(root.left, k)
        root.left = right
        update(root)
        return (left, root)
    else:
        # split point is in right subtree
        left, right = split(root.right, k - get_size(root.left) - 1)
        root.right = left
        update(root)
        return (root, right)


def merge(left, right):
    if not left or not right:
        return left or right
    if left.prio > right.prio:
        left.right = merge(left.right, right)
        update(left)
        return left
    else:
        right.left = merge(left, right.left)
        update(right)
        return right


def inorder(root, out):
    """collect values in-order"""
    if not root:
        return
    inorder(root.left, out)
    out.append(root.val)
    inorder(root.right, out)


