import sys
import math

def read_ints():
    return list(map(int, sys.stdin.read().split()))

def next_power_of_two(x):
    return 1 << (x - 1).bit_length()

def fft(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]
    length = 2
    while length <= n:
        ang = 2 * math.pi / length * (-1 if invert else 1)
        wlen = complex(math.cos(ang), math.sin(ang))
        for i in range(0, n, length):
            w = 1+0j
            half = length // 2
            for j in range(i, i + half):
                u = a[j]
                v = a[j + half] * w
                a[j] = u + v
                a[j + half] = u - v
                w *= wlen
        length <<= 1
    if invert:
        for i in range(n):
            a[i] /= n

def convolve(arr):
    n = len(arr)
    fa = [complex(x, 0) for x in arr] + [0j] * (n - len(arr))
    fft(fa, False)
    for i in range(len(fa)):
        fa[i] *= fa[i]
    fft(fa, True)
    res = [int(round(fa[i].real)) for i in range(len(fa))]
    return res

