class Dinic:
    class Edge:
        __slots__ = ("to", "rev", "cap")
        def __init__(self, to: int, rev: int, cap: int):
            self.to = to          # destination node
            self.rev = rev        # index of reverse edge in adjacency list of 'to'
            self.cap = cap        # residual capacity

    def __init__(self, n: int):
        self.n = n
        self.graph = [[] for _ in range(n)]

    def add_edge(self, fr: int, to: int, cap: int = 1):
        fwd = Dinic.Edge(to, len(self.graph[to]), cap)
        rev = Dinic.Edge(fr, len(self.graph[fr]), 0)
        self.graph[fr].append(fwd)
        self.graph[to].append(rev)

    def bfs_level(self, s: int, t: int):
        level = [-1] * self.n
        q = deque([s])
        level[s] = 0
        while q:
            v = q.popleft()
            for e in self.graph[v]:
                if e.cap and level[e.to] < 0:
                    level[e.to] = level[v] + 1
                    q.append(e.to)
        self.level = level
        return level[t] != -1

    def dfs_flow(self, v: int, t: int, f: int):
        if v == t:
            return f
        for i in range(self.it[v], len(self.graph[v])):
            self.it[v] = i
            e = self.graph[v][i]
            if e.cap and self.level[v] + 1 == self.level[e.to]:
                d = self.dfs_flow(e.to, t, min(f, e.cap))
                if d:
